  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "contract_number",
    "signing_date",
    "start_date",
    "end_date",
    "provider_name",
    "provider_cui",
    "beneficiary_name",
    "beneficiary_cui",
    "contract_value",
    "currency"
  ],
  "properties": {
    "contract_number": {
      "type": "string"
    },
    "signing_date": {
      "type": "string",
      "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
    },
    "start_date": {
      "type": "string",
      "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
    },
    "end_date": {
      "type": "string",
      "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
