    "provider_name": {
      "type": "string"
    },
    "provider_cui": {
      "type": "string"
    },
    "beneficiary_name": {
      "type": "string"
    },
    "beneficiary_cui": {
      "type": "string"
    },
    "contract_value": {
      "type": "number"
